.616196155548,"yaw":-28.809324692668999},{"cf":[23.833187103271486,14.765820503234864,-14.240549087524414,1,0,0,0,0.965925931930542,0.2588190734386444,0,-0.2588190734386444,0.965925931930542],"t":1083.6162042617798,"k":"cam","fov":70},{"y":8.577506065368653,"x":23.833187103271486,"k":"cf","z":-31.737577438354493,"t":1083.6328973770142,"yaw":-28.809324692668999},{"cf":[23.833187103271486,14.765819549560547,-14.240550994873047,1,0,0,0,0.9659258127212524,0.258819043636322,0,-0.258819043636322,0.9659258127212524],"t":1083.6329057216645,"k":"cam","fov":70},{"y":8.577506065368653,"x":23.833187103271486,"k":"cf","z":-31.737577438354493,"t":1083.6496186256409,"yaw":-28.809324692668999},{"cf":[23.833187103271486,14.765820503234864,-14.240549087524414,1,0,0,0,0.965925931930542,0.2588190734386444,0,-0.2588190734386444,0.965925931930542],"t":1083.6496279239655,"k":"cam","fov":70},{"y":8.577506065368653,"x":23.833187103271486,"k":"cf","z":-31.737577438354493,"t":1083.6664865016938,"yaw":-28.809324692668999},{"cf":[23.833187103271486,14.765819549560547,-14.240550994873047,1,0,0,0,0.9659258127212524,0.258819043636322,0,-0.258819043636322,0.9659258127212524],"t":1083.6664953231812,"k":"cam","fov":70},{"y":8.577506065368653,"x":23.833187103271486,"k":"cf","z":-31.737577438354493,"t":1083.683979511261,"yaw":-28.809324692668999},{"cf":[23.833187103271486,14.765820503234864,-14.240549087524414,1,0,0,0,0.965925931930542,0.2588190734386444,0,-0.2588190734386444,0.965925931930542],"t":1083.683987379074,"k":"cam","fov":70},{"y":8.577506065368653,"x":23.833187103271486,"k":"cf","z":-31.737577438354493,"t":1083.7006251811982,"yaw":-28.809324692668999},{"cf":[23.833187103271486,14.765819549560547,-14.240550994873047,1,0,0,0,0.9659258127212524,0.258819043636322,0,-0.258819043636322,0.9659258127212524],"t":1083.7006340026856,"k":"cam","fov":70},{"y":8.577506065368653,"x":23.833187103271486,"k":"cf","z":-31.737577438354493,"t":1083.715518951416,"yaw":-28.809324692668999},{"cf":[23.83318710327148